import { describe, expect, it } from "vitest";
import { rowsToTrainees } from "./csvParser";
import { SAMPLE_TRAINEES_DATA } from "./templates";

describe("templates: compatibility with csvParser", () => {
  it("parses the sample template trainees without any errors", () => {
    // Reconstruct the spreadsheet matrix generated by the template
    const headers = ["Nom", "Prénom", "Email"];
    const rows = [
      headers,
      ...SAMPLE_TRAINEES_DATA.map((t) => [t.lastName, t.firstName, t.email]),
    ];

    const result = rowsToTrainees(rows);

    expect(result.errors).toEqual([]);
    expect(result.trainees).toHaveLength(SAMPLE_TRAINEES_DATA.length);
    expect(result.trainees[0]).toEqual({
      line: 2,
      fullName: "Claire Dupont",
      email: "claire.dupont@exemple.fr",
    });
    expect(result.trainees[1]).toEqual({
      line: 3,
      fullName: "Lucas Martin",
      email: "lucas.martin@exemple.fr",
    });
  });
});
